class Solution {
    public boolean isValid(String s){
        StringBuilder stack=new StringBuilder();
        for(char ch:s.toCharArray()){
            stack.append(ch);
            int n=stack.length();
            if(n>=3&&stack.charAt(n-3)=='a'&&stack.charAt(n-2)=='b'&&stack.charAt(n-1)=='c')stack.setLength(n-3);
        }
        return stack.length()==0;
    }
}

code.kotlin:
class Solution {
    fun isValid(s:String):Boolean{
        val stack=StringBuilder();
        for(ch in s){
            stack.append(ch);
            val n=stack.length;
            if(n>=3&&stack[n-3]=='a'&&stack[n-2]=='b'&&stack[n-1]=='c')stack.setLength(n-3)
        };
        return stack.isEmpty()
    }
}

